fn solve(s: &Vec<char>) -> Vec<char> {
    // Start by cloning the input so we can build the result
    let mut result = s.clone();

    // Since the input is guaranteed non-empty, unwrap is safe here
    if let Some(&last_char) = s.last() {
        if last_char == 's' {
            // If it ends with 's', append "es"
            result.push('e');
            result.push('s');
        } else {
            // Otherwise, just append 's'
            result.push('s');
        }
    }

    result
}

fn main() {
    let word1: Vec<char> = "bus".chars().collect();
    let word2: Vec<char> = "cat".chars().collect();

    let plural1 = solve(&word1);
    let plural2 = solve(&word2);

    println!("{}", plural1.iter().collect::<String>()); // "buses"
    println!("{}", plural2.iter().collect::<String>()); // "cats"
}